<?php
require_once __DIR__.'/../config.php'; require_once __DIR__.'/../includes/functions.php'; $pageTitle='Messages'; require_role(['admin','teacher','student','parent']); require_once __DIR__.'/../includes/header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$recipient=(int)$_POST['recipient_id'];$st=$pdo->prepare("SELECT id,full_name,email,phone FROM users WHERE id=? AND status='active' AND id<>?");$st->execute([$recipient,user()['id']]);$r=$st->fetch();if(!$r){$error='Recipient is unavailable.';}else{$body=trim($_POST['body']);$subject=trim($_POST['subject']);if($body===''||$subject===''){$error='Subject and message are required.';}else{$st=$pdo->prepare("INSERT INTO messages(sender_id,recipient_id,subject,body) VALUES(?,?,?,?)");$st->execute([user()['id'],$recipient,$subject,$body]);notify_user($pdo,$recipient,$subject,$body);audit($pdo,'send','messages',(int)$pdo->lastInsertId());$sent=true;}}}
$recipients=$pdo->query("SELECT id,full_name,role FROM users WHERE status='active' ORDER BY role,full_name")->fetchAll();$in=$pdo->prepare("SELECT m.*,u.full_name sender FROM messages m JOIN users u ON u.id=m.sender_id WHERE m.recipient_id=? ORDER BY m.sent_at DESC LIMIT 200");$in->execute([user()['id']]);$messages=$in->fetchAll();
?><h2>Messages</h2><?php if(!empty($sent)): ?><div class="alert alert-success">Message sent. Enabled email/SMS/WhatsApp channels have been queued for delivery.</div><?php endif;?><?php if(!empty($error)): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card p-4 mb-4"><h5>Send message</h5><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row g-3"><div class="col-md-4"><label>Recipient</label><select class="form-select" name="recipient_id" required><?php foreach($recipients as $r): ?><?php if((int)$r['id']===(int)user()['id'])continue; ?><option value="<?=$r['id']?>"><?=e($r['full_name'].' — '.$r['role'])?></option><?php endforeach;?></select></div><div class="col-md-8"><label>Subject</label><input class="form-control" name="subject" required></div><div class="col-12"><label>Message</label><textarea class="form-control" rows="5" name="body" required></textarea></div><div class="col-12"><button class="btn btn-primary">Send</button></div></div></form></div><div class="card p-3"><h5>Inbox</h5><?php foreach($messages as $m): ?><div class="border-bottom py-3"><strong><?=e($m['subject'])?></strong><div class="small text-muted">From <?=e($m['sender'])?> · <?=e($m['sent_at'])?></div><p class="mb-0 mt-2"><?=nl2br(e($m['body']))?></p></div><?php endforeach;?><?php if(!$messages): ?><div class="text-muted">No messages.</div><?php endif;?></div><?php require __DIR__.'/../includes/footer.php';
